int main(int argc, char **argv) {
  if (argc < 2) { fprintf(stderr, "usage: %s <file.obc> [args...]\n", argv[0]); return 2; }
#ifdef _WIN32
  _setmode(_fileno(stdout), _O_BINARY);
  _setmode(_fileno(stdin), _O_BINARY);
#endif
  initBasicTypes();
  if (setjmp(obJmp)) return 1;
  VM *vm = vmLoad(argv[1]);
  vmSetArgs(argc - 2, argv + 2);
  rtEnterBody(vm);
  procTab[0][0](vm);
  fflush(stdout);
  return vm->haltCode;
}
